typedef unsigned char u_char;
typedef unsigned int u_int;
typedef unsigned long u_long;

enum { NGLTEX_TGA, NGLTEX_TIM2, NGLTEX_IFL, NGLTEX_ATE };
enum nglGSRegType {
  NGL_GS_FOG, NGL_GS_PRMODE, NGL_GS_TEX0_1, NGL_GS_TEX1_1,
  NGL_GS_TEXCLUT, NGL_GS_MIPTBP1_1, NGL_GS_MIPTBP2_1,
  NGL_GS_CLAMP_1, NGL_GS_TEXA, NGL_GS_ALPHA_1, NGL_GS_TEST_1,
  NGL_GS_PABE, NGL_GS_RGBAQ, NGL_GS_NUM_REGS
};
enum { NGLMAP_POINT_FILTER = 1, NGLMAP_TRILINEAR_FILTER = 4 };
enum { SCE_GS_TEXFLUSH = 0x3f };

struct sceGsTex0 {
  u_long TBP0:14, TBW:6, PSM:6, TW:4, TH:4, TCC:1, TFX:2,
         CBP:14, CPSM:4, CSM:1, CSA:5, CLD:3;
};
struct sceGsTex1 {
  u_long LCM:1, unused0:1, MXL:3, MMAG:1, MMIN:3, MTBA:1,
         unused1:9, L:2, unused2:11, K:12, unused3:20;
};
struct nglTexture {
  char pad0[0x10];
  u_char Type;
  char pad1[0x13];
  u_int NFrames;
  nglTexture **Frames;
  char pad2[0xcc];
  u_long GsTexA;
  u_long GsTex0;
  u_long GsTex1;
};
struct nglScene { char pad[0x10]; nglTexture *RenderTarget; };

extern nglTexture *nglWhiteTex;
extern u_int nglTextureAnimFrame;
extern nglScene *nglCurScene;
extern u_int nglGifRegCount;
extern u_char nglGifRegIdx[128];
extern u_long nglGifRegVal[128];
extern u_int nglGSRegIdx[NGL_GS_NUM_REGS];
__asm__(".equ nglWhiteTex,0x004BC034");
__asm__(".equ nglTextureAnimFrame,0x004BBF88");
__asm__(".equ nglCurScene,0x004BBD04");
__asm__(".equ nglGifRegCount,0x004BCA78");
__asm__(".equ nglGifRegIdx,0x004BCA80");
__asm__(".equ nglGifRegVal,0x004BCB00");
__asm__(".equ nglGSRegIdx,0x004B7118");

inline void nglVif1AddGSReg(nglGSRegType Reg, u_long Val)
{
  nglGifRegIdx[nglGifRegCount] = nglGSRegIdx[Reg];
  nglGifRegVal[nglGifRegCount] = Val;
  nglGifRegCount++;
}
inline void nglVif1AddRawGSReg(u_int Reg, u_long Val)
{
  nglGifRegIdx[nglGifRegCount] = Reg;
  nglGifRegVal[nglGifRegCount] = Val;
  nglGifRegCount++;
}
#define NGL_DISABLE_MIPMAPS 1
#define START_PROF_TIMER(x)
#define STOP_PROF_TIMER(x)
#define SCE_GS_SET_TEX1(lcm,mxl,mmag,mmin,mtba,l,k) \
  ((u_long)(lcm) | ((u_long)(mxl)<<2) | ((u_long)(mmag)<<5) | \
   ((u_long)(mmin)<<6) | ((u_long)(mtba)<<9) | ((u_long)(l)<<19) | \
   ((u_long)(k)<<32))

void nglVif1AddSetTexture( nglTexture* Tex, u_int MapFlags, float MipRatio )
{
  START_PROF_TIMER( proftimer_section_set_texture );

  if (!Tex) Tex = nglWhiteTex;

  if ( Tex->Type == NGLTEX_IFL || Tex->Type == NGLTEX_ATE )
    Tex = Tex->Frames[nglTextureAnimFrame % Tex->NFrames];

  if ( Tex->Type == NGLTEX_TGA )
  {
    nglVif1AddGSReg( NGL_GS_TEX0_1, Tex->GsTex0 );
    nglVif1AddGSReg( NGL_GS_TEX1_1, Tex->GsTex1 );
    nglVif1AddGSReg( NGL_GS_TEXA, Tex->GsTexA );
  }
  else
  if ( Tex->Type == NGLTEX_TIM2 )
  {
    if ( ( (sceGsTex0*)&Tex->GsTex0 )->PSM == 20 )
    {
      ( (sceGsTex0*)&Tex->GsTex0 )->PSM = 19;
      ( (sceGsTex0*)&Tex->GsTex0 )->CLD = 1;
      nglVif1AddGSReg( NGL_GS_TEX0_1, Tex->GsTex0 );

      ( (sceGsTex0*)&Tex->GsTex0 )->PSM = 20;
      ( (sceGsTex0*)&Tex->GsTex0 )->CLD = 0;
      nglVif1AddGSReg( NGL_GS_TEX0_1, Tex->GsTex0 );
    }
    else
      nglVif1AddGSReg( NGL_GS_TEX0_1, Tex->GsTex0 );

#if !NGL_DISABLE_MIPMAPS
#endif
    {
      u_int MinFilter = 1, MagFilter = 1;
      if ( MapFlags & NGLMAP_POINT_FILTER )
        MinFilter = MagFilter = 0;
      nglVif1AddGSReg(
        NGL_GS_TEX1_1,
        SCE_GS_SET_TEX1( 0, 0, MagFilter, MinFilter, 0, 0, 0 ) );
    }
    nglVif1AddGSReg( NGL_GS_TEXA, Tex->GsTexA );
  }

  if ( Tex == nglCurScene->RenderTarget )
    nglVif1AddRawGSReg( SCE_GS_TEXFLUSH, 0 );

  STOP_PROF_TIMER( proftimer_section_set_texture );
}
